<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mlogisticsmodel extends CI_Model {    function fnGetInfo($VarBom='',$VarStatus='',$VarId='') {        $this->db->select('id,consignorexporter,consignee,importer,forwardingagent,clearingagent,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_LOGISTICS);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarId<>'') {            $ArrWhere['id'] 				                = $VarId;        }        if($VarBom<>'') {            $ArrWhere['bomname'] 		                    = $VarBom;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		                = $this->db->get()->result_array();        return $ArrResultList;    }    function saveInfo($ArrUpdateData){        $VarId                                                  = $ArrUpdateData['id'];        if($VarId=="") {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_LOGISTICS,$ArrUpdateData);                $VarId                                          = $this->db->insert_id();                $ArrResult['errcode']						    = 1;                $ArrResult['msg']							    = '';                $ArrResult['id']							    = $VarId;                $ArrResult['eid']							    = urlencode(base64_encode($VarId));        } else {                if($this->db->update(KN_MASTER_LOGISTICS,$ArrUpdateData,array('id'=>$VarId))) {                    $ArrResult['errcode']					    = 1;                    $ArrResult['msg']							= '';                    $ArrResult['id']							= $VarId;                    $ArrResult['eid']							= urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode']						= '-1';                    $ArrResult['msg']							= 'Invalid Data!';                }        }        return $ArrResult;    }    function fnCount($VarCsexporter='',$VarForwardingagent='',$VarClearingAgent='',$VarImporter='',$VarConsignee='',$VarStatus='',$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $ArrWhere                   = array();        if($VarCsexporter<>'') {            $ArrWhere[]             = "l.consignorexporter like '%".$VarCsexporter."%'";        }        if($VarForwardingagent<>'') {            $ArrWhere[]             = "l.forwardingagent like '%".$VarForwardingagent."%' ";        }        if($VarClearingAgent<>'') {            $ArrWhere[]             = "l.clearingagent like '%".$VarClearingAgent."%'";        }        if($VarImporter<>'') {            $ArrWhere[]             = "l.importer like '%".$VarImporter."%'";        }        if($VarConsignee<>'') {            $ArrWhere[]             = "l.consignee like '%".$VarConsignee."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "l.consignorexporter LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "l.status=".$VarStatus;        } else {            $ArrWhere[]             = "l.status in(1,2)";        }        $ArrWhere[]                 = "l.companyid = ".$userInfo['companyid'];        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere);        }            $VarSqlLab              = "SELECT count(1) as trec  FROM ".KN_MASTER_LOGISTICS." AS l INNER JOIN ".KN_USERS." AS u ON l.updatedby = u.id WHERE ".$VarWhere ;        $ObjRows					= $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarCsexporter='',$VarForwardingagent='',$VarClearingAgent='',$VarImporter='',$VarConsignee='',$VarStatus='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array('l.consignorexporter','l.forwardingagent','l.clearingagent','l.importer','l.consignee','l.status','u.contactname','l.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'l.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarCsexporter<>'') {            $ArrWhere[]             = "l.consignorexporter like '%".$VarCsexporter."%'";        }        if($VarForwardingagent<>'') {            $ArrWhere[]             = "l.forwardingagent like '%".$VarForwardingagent."%' ";        }        if($VarClearingAgent<>'') {            $ArrWhere[]             = "l.clearingagent like '%".$VarClearingAgent."%'";        }        if($VarImporter<>'') {            $ArrWhere[]             = "l.importer like '%".$VarImporter."%'";        }        if($VarConsignee<>'') {            $ArrWhere[]             = "l.consignee like '%".$VarConsignee."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "l.consignorexporter LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "l.status=".$VarStatus;        } else {            $ArrWhere[]             = "l.status in(1,2)";        }        $ArrWhere[]                 = "l.companyid = ".$userInfo['companyid'];        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ;        }        $VarSqlLab                  = "SELECT l.id,l.consignorexporter,l.clearingagent,l.forwardingagent,l.importer,l.consignee,u.contactname,l.datecreated,l.dateupdated,l.status FROM ".KN_MASTER_LOGISTICS." AS l INNER JOIN ".KN_USERS." AS u ON l.updatedby = u.id WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnDel($VarId='',$VarUpdatedBy='') {        if(@$VarId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_LOGISTICS,$ArrUpdateData,array('id'=>$VarId))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarId;                $ArrResult['eid']							= urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_LOGISTICS,array('status' => $optvalue))) {            return true;        }        return false;    }}   